 86	export function command(executable, args, { cwd, env, timeout = 30_000, signal } = {}) {
 87	  return new Promise((resolveCommand, reject) => {
 88	    const child = spawn(executable, args, {
 89	      cwd,
 90	      env,
 91	      stdio: ['ignore', 'pipe', 'pipe'],
 92	      detached: process.platform !== 'win32',
 93	    });
 94	    let stdout = '';
 95	    let bytes = 0;
 96	    let failure;
 97	    let killTimer;
 98	    function kill(processSignal) {
 99	      try {
100	        if (process.platform === 'win32') child.kill(processSignal);
101	        else process.kill(-child.pid, processSignal);
102	      } catch (error) {
103	        if (error.code !== 'ESRCH') failure ??= error;
104	      }
105	    }
106	    function stop(reason) {
107	      if (failure) return;
108	      failure = new Error(reason);
109	      kill('SIGTERM');
110	      killTimer = setTimeout(() => kill('SIGKILL'), 2000);
111	    }
112	    const timer = setTimeout(() => stop('command timed out'), timeout);
113	    const abort = () => stop('cancelled');
114	    signal?.addEventListener('abort', abort, { once: true });
115	    if (signal?.aborted) abort();
116	    child.stdout.on('data', (chunk) => {
117	      bytes += chunk.length;
118	      if (bytes > MAX_OUTPUT) stop('command output limit exceeded');
119	      else stdout += chunk.toString();
120	    });
121	    // Runtime logs can contain configuration. Drain stderr without retaining it.
122	    child.stderr.resume();
123	    child.on('error', (error) => {
124	      failure = new Error(`cannot start ${executable}: ${error.code}`);
125	    });
126	    child.on('close', (code) => {
127	      clearTimeout(timer);
128	      clearTimeout(killTimer);
129	      signal?.removeEventListener('abort', abort);
130	      if (failure) reject(failure);
131	      else if (code !== 0) reject(new Error(`${executable} ${args[0]} exited ${code}`));
132	      else resolveCommand(stdout.trim());
133	    });
134	  });
135	}
