    13	    { name: 'frontend-ar', url: 'http://frontend:3000/ar/auth/login', locale: 'ar' },
    14	    { name: 'auth-methods', url: 'http://backend:5000/api/auth/methods' },
    15	  ];
    16	  const checked = [];
    17	  for (const target of targets) {
    18	    let response;
    19	    let body = '';
    20	    let size = 0;
    21	    const signal = AbortSignal.timeout(timeout);
    22	    try {
    23	      response = await fetchResponse(target.url, { redirect: 'manual', signal });
    24	      if (response.status !== 200 || response.headers.get('location')) {
    25	        await response.body?.cancel().catch(() => undefined);
    26	        return { failure: target.name, reason: 'unexpected HTTP status or redirect' };
    27	      }
    28	      const decoder = new TextDecoder();
    29	      for await (const chunk of response.body) {
    30	        size += chunk.length;
    31	        if (size > maxBytes) {
    32	          return { failure: target.name, reason: 'response too large' };
    33	        }
    34	        body += decoder.decode(chunk, { stream: true });
    35	      }
    36	      body += decoder.decode();
    37	    } catch {
    38	      return {
    39	        failure: target.name,
    40	        reason: signal.aborted ? 'request timed out' : 'request failed',
    41	      };
    42	    }
    43	    if (target.locale) {
    44	      if (!body.includes(`lang="${target.locale}"`) || !body.includes('<form')) {
    45	        return { failure: target.name, reason: 'login document contract' };
    46	      }
    47	    } else {
    48	      let value;
    49	      try {
    50	        value = JSON.parse(body);
    51	      } catch {
    52	        return { failure: target.name, reason: 'invalid JSON' };
    53	      }
    54	      if (target.name === 'backend-health') {
    55	        if (
    56	          !value ||
    57	          Object.keys(value).sort().join(',') !== 'status,timestamp' ||
    58	          value.status !== 'healthy' ||
    59	          !Number.isFinite(Date.parse(value.timestamp))
    60	        )
    61	          return { failure: target.name, reason: 'health response contract' };
    62	      } else if (target.name === 'nginx-health') {
    63	        if (!value || Object.keys(value).join(',') !== 'status' || value.status !== 'healthy') {
